            grant <= 4'b0000;  
            if (req0) begin  
                grant <= 4'b0001;  
            end else if (req1) begin  
                grant <= 4'b0010;  
            end else if (req2) begin  
                grant <= 4'b0100;  
            end else if (req3) begin  
                grant <= 4'b1000;  
            end  
        end  
    end  
endmodule

