module linked_list_traversal(clk, reset, data_out);  
    input clk;  
    input reset;  
    output reg data_out;  

    reg [4:0] linked_list;  
    reg [2:0] current_index;  

    initial begin  
        linked_list = 5'b10101; // Example linked list values  
        current_index = 3'b000;  
        data_out = 1'b0;  
    end  

